-- Check: sample records per register (10 each).
SELECT l.register_key, count(r.id) AS records
FROM public.local_registers l
LEFT JOIN public.local_register_records r ON r.register_id = l.id AND r.is_deleted = FALSE
WHERE l.id IN ('00000000-0000-4000-9001-00000000004c'::uuid, '00000000-0000-4000-9001-00000000004d'::uuid, '00000000-0000-4000-9001-00000000004e'::uuid, '00000000-0000-4000-9001-00000000004f'::uuid, '00000000-0000-4000-9001-000000000050'::uuid, '00000000-0000-4000-9001-000000000051'::uuid, '00000000-0000-4000-9001-000000000052'::uuid, '00000000-0000-4000-9001-000000000053'::uuid, '00000000-0000-4000-9001-000000000054'::uuid, '00000000-0000-4000-9001-000000000055'::uuid)
GROUP BY l.register_key ORDER BY l.register_key;
